#include "port.h"
#include "mem.h"
#include "ar.h"
#include "hashtab.h"
#include "nl.h"
#include "nl_int.h"


/*internal*/
nl_direction
nl_direction_reverse (nl_direction direction)
{
  switch (direction) {
  case nl_direction_in:
    return nl_direction_out;
  case nl_direction_out:
    return nl_direction_in;
  case nl_direction_inout:
    return nl_direction_inout;
  case nl_direction_unknown:
    return nl_direction_unknown;
  default:
    ASSERT (0);
  }
}
